___CSS_LOADER_EXPORT___.push([module.id, ".gallery-images[data-v-2416f4d3]{grid-gap:1rem;align-items:stretch;display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr))}.image-container[data-v-2416f4d3]{max-width:100%;position:relative}.delete-button[data-v-2416f4d3]{align-items:center;background-color:var(--bs-danger);border:none;border-radius:50%;color:var(--bs-white);display:flex;font-size:14px;height:24px;justify-content:center;position:absolute;right:-8px;top:-8px;width:24px;z-index:1}.selected-image[data-v-2416f4d3]{height:100px;-o-object-fit:cover;object-fit:cover;width:100%}", "",{"version":3,"sources":["webpack://./resources/js/vue/components/branch/BranchGalleryOffcanvas.vue"],"names":[],"mappings":"AAmHA,iCAGE,aAAc,CACd,mBAAoB,CAHpB,YAAa,CACb,yDAGF,CACA,kCAEE,cAAe,CADf,iBAEF,CAEA,gCAaE,kBAAmB,CAPnB,iCAAkC,CAClC,WAAY,CACZ,iBAAkB,CAHlB,qBAAsB,CAOtB,YAAa,CADb,cAAe,CADf,WAAY,CAIZ,sBAAuB,CAbvB,iBAAkB,CAElB,UAAW,CADX,QAAS,CAOT,UAAW,CALX,SAWF,CAEA,iCAEE,YAAa,CADb,mBAAiB,CAAjB,gBAAiB,CAEjB,UACF","sourcesContent":["<template>\r\n  <form @submit.prevent=\"formSubmit\">\r\n    <div class=\"offcanvas offcanvas-end\" tabindex=\"-1\" id=\"branch-gallery-form\" aria-labelledby=\"form-offcanvasLabel\">\r\n      <div class=\"offcanvas-header border-bottom\" v-if=\"branch\">\r\n        <h6 class=\"m-0 h5\">\r\n          {{ $t('branch.singular_title') }}: <span>{{ branch.name }}</span>\r\n        </h6>\r\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"offcanvas\" aria-label=\"Close\"></button>\r\n      </div>\r\n      <div class=\"d-flex flex-column border-bottom p-3\">\r\n        <div class=\"\">\r\n          <label class=\"form-label btn btn-info d-block my-0\" for=\"branch_feature_image\">{{ $t('messages.upload_images') }}</label>\r\n          <input ref=\"fileInputRef\" type=\"file\" class=\"form-control d-none\" id=\"branch_feature_image\" accept=\".jpeg, .jpg, .png, .gif\" multiple @change=\"handleImageUpload\" />\r\n        </div>\r\n      </div>\r\n      <div class=\"offcanvas-body\">\r\n        <div v-if=\"featureImages.length === 0\" class=\"text-center mb-0\">{{ $t('messages.data_not_available') }}</div>\r\n        <div v-else>\r\n          <div class=\"gallery-images\">\r\n            <div v-for=\"(feature, index) in featureImages\" :key=\"index\" class=\"image-container col\">\r\n              <button class=\"delete-button\" @click=\"removeImage(index)\" type=\"button\">\r\n                <i class=\"fa-solid fa-xmark\"></i>\r\n              </button>\r\n              <img :src=\"feature.full_url\" alt=\"Selected Image\" class=\"img-fluid selected-image\" />\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div class=\"offcanvas-footer\">\r\n        <p class=\"text-center mb-0\">\r\n          <small>{{ $t('messages.gallery_for_branch') }}</small>\r\n        </p>\r\n        <div class=\"d-grid gap-3 p-3\">\r\n          <button class=\"btn btn-primary d-block\"><i class=\"fa-solid fa-floppy-disk mx-2\"></i>{{ $t('messages.upload') }}</button>\r\n          <button class=\"btn btn-outline-primary d-block\" type=\"button\" data-bs-dismiss=\"offcanvas\"><i class=\"fa-solid fa-angles-left\"></i>{{ $t('messages.close') }}</button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </form>\r\n</template>\r\n\r\n<script setup>\r\nimport { ref } from 'vue'\r\nimport { GET_GALLERY_URL, POST_GALLERY_URL } from '../../constants/branch'\r\nimport { useRequest, useModuleId } from '@/helpers/hooks/useCrudOpration'\r\nimport { createRequestWithFormData } from '@/helpers/utilities'\r\n\r\n// Request\r\nconst { getRequest } = useRequest()\r\n\r\nconst fileInputRef = ref(null)\r\n\r\n// Branch Name Values\r\nconst branch = ref(null)\r\nconst branchId = useModuleId(() => {\r\n  getRequest({ url: GET_GALLERY_URL, id: branchId.value }).then((res) => {\r\n    if (res.status) {\r\n      branch.value = res.branch\r\n      featureImages.value = res.data\r\n    }\r\n  })\r\n}, 'branch_gallery')\r\n\r\n// Select Images\r\nlet featureImages = ref([])\r\n\r\n// Function for Images in Array\r\nconst handleImageUpload = (event) => {\r\n  const files = event.target.files\r\n\r\n  for (let i = 0; i < files.length; i++) {\r\n    const file = files[i]\r\n    const reader = new FileReader()\r\n\r\n    reader.readAsDataURL(file)\r\n\r\n    reader.onload = () => {\r\n      featureImages.value.push({ file: file, full_url: reader.result, id: null })\r\n      fileInputRef.value.value = ''\r\n    }\r\n  }\r\n}\r\n// Function to delete Images\r\nconst removeImage = (index) => {\r\n  featureImages.value.splice(index, 1)\r\n  window.successSnackbar('Image removed successfully')\r\n}\r\n\r\n// Reload Datatable, SnackBar Message, Alert, Offcanvas Close\r\nconst errorMessages = ref([])\r\nconst reset_close_offcanvas = (res) => {\r\n  if (res.status) {\r\n    window.successSnackbar(res.message)\r\n    bootstrap.Offcanvas.getInstance('#branch-gallery-form').hide()\r\n  } else {\r\n    window.errorSnackbar(res.message)\r\n    errorMessages.value = res.all_message\r\n  }\r\n}\r\n\r\n//Form Submit\r\nconst formSubmit = () => {\r\n  let formData = new FormData()\r\n  Object.keys(featureImages.value).map((index) => {\r\n    Object.keys(featureImages.value[index]).map((fieldName) => {\r\n      let value = featureImages.value[index][fieldName]\r\n      if (fieldName == 'full_url') value = ''\r\n      formData.append(`gallery[${index}][${fieldName}]`, value)\r\n    })\r\n  })\r\n  createRequestWithFormData(POST_GALLERY_URL(branchId.value), { Accept: 'application/json' }, formData).then((res) => reset_close_offcanvas(res))\r\n}\r\n</script>\r\n\r\n<style scoped>\r\n.gallery-images {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fill, minmax(104px, 1fr));\r\n  grid-gap: 1rem;\r\n  align-items: stretch;\r\n}\r\n.image-container {\r\n  position: relative;\r\n  max-width: 100%;\r\n}\r\n\r\n.delete-button {\r\n  position: absolute;\r\n  top: -8px;\r\n  right: -8px;\r\n  z-index: 1;\r\n  color: var(--bs-white);\r\n  background-color: var(--bs-danger);\r\n  border: none;\r\n  border-radius: 50%;\r\n  width: 24px;\r\n  height: 24px;\r\n  font-size: 14px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n}\r\n\r\n.selected-image {\r\n  object-fit: cover;\r\n  height: 100px;\r\n  width: 100%;\r\n}\r\n</style>\r\n"],"sourceRoot":""}]);
